using Microsoft.AspNetCore.Mvc;using NovaStore.Models;using NovaStore.Services;
namespace NovaStore.Controllers;public class AdminController(StoreService store,IConfiguration config):Controller {bool Authorized()=>HttpContext.Session.GetString("admin")=="yes";public IActionResult Login()=>View();[HttpPost,ValidateAntiForgeryToken]public IActionResult Login(string password){if(password==config["AdminPassword"]){HttpContext.Session.SetString("admin","yes");return RedirectToAction("Index");}ViewBag.Error="Incorrect password";return View();}public IActionResult Logout(){HttpContext.Session.Remove("admin");return RedirectToAction("Index","Home");}public IActionResult Index(){if(!Authorized())return RedirectToAction("Login");ViewBag.Orders=store.Orders();return View(store.Products());}public IActionResult Edit(int id=0){if(!Authorized())return RedirectToAction("Login");return View(id==0?new Product():store.Find(id)??new Product());}[HttpPost,ValidateAntiForgeryToken]public IActionResult Edit(Product product){if(!Authorized())return RedirectToAction("Login");if(!ModelState.IsValid)return View(product);store.Upsert(product);return RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public IActionResult Delete(int id){if(!Authorized())return RedirectToAction("Login");store.Delete(id);return RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public IActionResult Status(string id,string status){if(!Authorized())return RedirectToAction("Login");if(new[]{"New","Processing","Shipped","Delivered","Cancelled"}.Contains(status))store.UpdateStatus(id,status);return RedirectToAction("Index");}}
